package com.expensetracker.app.data.sound

import android.content.Context
import android.media.AudioAttributes
import android.media.MediaPlayer
import android.util.Base64
import java.io.File

/**
 * Native adapter for UI SFX soft-pack assets.
 * UI SFX code is MIT licensed and its generated audio is CC0-1.0.
 */
object UISfxSoundPlayer {
    private val sounds: Map<String, String> = mapOf(
        "notification" to "",
        "success" to "",
        "warning" to "",
        "error" to "",
        "complete" to "",
        "reward" to "",
        "check" to "",
        "select" to ""
    )

    fun play(context: Context, cue: String) {
        val encoded = sounds[cue] ?: return
        val bytes = Base64.decode(encoded, Base64.DEFAULT)
        val file = File(context.cacheDir, "uisfx_$cue.mp3")
        file.writeBytes(bytes)

        val player = MediaPlayer()
        player.setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_NOTIFICATION)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        player.setDataSource(file.absolutePath)
        player.setOnCompletionListener {
            it.release()
            file.delete()
        }
        player.setOnErrorListener { mp, _, _ ->
            mp.release()
            file.delete()
            true
        }
        player.prepare()
        player.start()
    }
}
